script:
let targets = ["ptrace", "prctl"];
for t in targets {
  let syms = find_symbols(t);
  for s in syms {
    if s.name == t || s.name.ends_with("::" + t) {
      let xrefs = get_xrefs(s.address);
      for x in xrefs {
        report_patch("Caller of " + s.name, x.from, "HIGH", "Calls " + s.name + " via " + x.instruction, "quick", "nop");
      }
    }
  }
}
